-- Migration 010: Integrate all 159 HRMN upstream models + 21 Free models with per-model pricing, request costs, and rate limits

ALTER TABLE models
    ADD COLUMN IF NOT EXISTS min_plan text NOT NULL DEFAULT 'free' CHECK (min_plan IN ('free', 'pro')),
    ADD COLUMN IF NOT EXISTS category text NOT NULL DEFAULT 'reasoning',
    ADD COLUMN IF NOT EXISTS input_price_per_m numeric(10,4) NOT NULL DEFAULT 0.0,
    ADD COLUMN IF NOT EXISTS output_price_per_m numeric(10,4) NOT NULL DEFAULT 0.0,
    ADD COLUMN IF NOT EXISTS request_cost integer NOT NULL DEFAULT 1,
    ADD COLUMN IF NOT EXISTS rpm_limit integer NOT NULL DEFAULT 20,
    ADD COLUMN IF NOT EXISTS rpd_limit integer NOT NULL DEFAULT 100;

-- Ensure public placeholder models have clean defaults
UPDATE models SET min_plan = 'free', category = 'reasoning', input_price_per_m = 0.0, output_price_per_m = 0.0, request_cost = 1, rpm_limit = 20, rpd_limit = 100 WHERE id LIKE 'varynth/public-%';

-- Upsert all 21 Free models + 145 Pro HRMN models into `models`
ON CONFLICT (id) DO UPDATE SET
    display_name = EXCLUDED.display_name,
    tier = EXCLUDED.tier,
    min_plan = EXCLUDED.min_plan,
    category = EXCLUDED.category,
    upstream_kind = EXCLUDED.upstream_kind,
    upstream_model = EXCLUDED.upstream_model,
    upstream_base_url = EXCLUDED.upstream_base_url,
    enabled = EXCLUDED.enabled,
    input_price_per_m = EXCLUDED.input_price_per_m,
    output_price_per_m = EXCLUDED.output_price_per_m,
    request_cost = EXCLUDED.request_cost,
    rpm_limit = EXCLUDED.rpm_limit,
    rpd_limit = EXCLUDED.rpd_limit,
    sort_order = EXCLUDED.sort_order;

-- Upsert provider_catalog
ON CONFLICT (id) DO UPDATE SET
    display_name = EXCLUDED.display_name,
    kind = EXCLUDED.kind,
    sort_order = EXCLUDED.sort_order;

-- Upsert provider_models
ON CONFLICT (provider_id, model_id) DO UPDATE SET
    display_name = EXCLUDED.display_name;
